def normal_from_points(p, q, r):
    """由平面上三点求法向量（叉积），返回未化简向量。"""
    return (q - p).cross(r - p)


def simplify_vec(v):
    """把向量按公因子约简到最简整系数方向（仅用于'简化取 n=...'的展示）。"""
    v = sp.Matrix([sp.simplify(c) for c in v])
